import type {ChatSession} from '../types/session.js';

// Spec: specs/hal-engine-config-hooks/spec.md#7
it('reports and cleans up a failed beforeSession before rejecting with the original error', async () => {
  const session: ChatSession = {
    sessionId: 'failed-setup',
    userId: 'deployer',
    entries: [{role: 'user', content: 'hello', timestamp: '2026-01-01T00:00:00.000Z'}],
  };
  const failure = new Error('session allocation failed');
  const events: string[] = [];
  const argumentsReceived: boolean[] = [];
  let allocated = false;
  const orchestrator = createChatOrchestrator(
    createMockProvider(),
    new PromptBuilder({identity: 'You are an assistant.'}),
    undefined,
    {
      hooks: {
        beforeSession: async current => {
          events.push('beforeSession');
          argumentsReceived.push(current === session);
          allocated = true;
          throw failure;
        },
        onError: async (current, error) => {
          events.push('onError');
          argumentsReceived.push(current === session, error === failure);
        },
        afterSession: async current => {
          events.push('afterSession');
          argumentsReceived.push(current === session);
          allocated = false;
        },
        beforeUserInput: async (_current, message) => {
          events.push('beforeUserInput');
          return message;
        },
        beforeModelResponse: async (_current, prompt) => {
          events.push('beforeModelResponse');
          return prompt;
        },
        afterModelResponse: async () => {
          events.push('afterModelResponse');
        },
      },
    }
  );

  const rejection: unknown = await orchestrator.processMessage(session).catch((error: unknown) => error);
  events.push('caller');

  expect({originalError: rejection === failure, events, argumentsReceived, allocated}).toEqual({
    originalError: true,
    events: ['beforeSession', 'onError', 'afterSession', 'caller'],
    argumentsReceived: [true, true, true, true],
    allocated: false,
  });
});
''')
